val uiState = MutableStateFlow(UiState())

viewModelScope.launch {
    repository.itemsFlow.collect { items ->
        uiState.value = uiState.value.copy(items = items)
    }
}

class MyViewModel : ViewModel() {
    fun load() {
        viewModelScope.launch { repository.refresh() }
    }
}

class Repo(ctx: Context) {
    private val appCtx = ctx.applicationContext
}

class ItemsAdapter : ListAdapter<Item, VH>(DIFF) {
    companion object {
        val DIFF = object : DiffUtil.ItemCallback<Item>() {
            override fun areItemsTheSame(a: Item, b: Item) = a.id == b.id
            override fun areContentsTheSame(a: Item, b: Item) = a == b
        }
    }
}

sealed class UiState {
    data object Loading : UiState()
    data class Error(val message: String) : UiState()
    data class Data(val items: List<Item>) : UiState()
}

class MyVm(private val state: SavedStateHandle) : ViewModel() {
    var query: String
        get() = state["query"] ?: ""
        set(value) { state["query"] = value }
}

val diff = object : DiffUtil.ItemCallback<Item>() {
    override fun areItemsTheSame(a: Item, b: Item) = a.id == b.id
    override fun areContentsTheSame(a: Item, b: Item) = a == b
}

